import{_ as s,o as i,c as n,a2 as e}from"./chunks/framework.CqGPl1zp.js";const t="/newx-doc/assets/Suno-%E7%A7%81%E6%9C%89.j4_Yu2Jy.png",k=JSON.parse('{"title":"【模型接入】Suno","description":"","frontmatter":{},"headers":[],"relativePath":"ai/suno.md","filePath":"ai/suno.md","lastUpdated":null}'),o={name:"ai/suno.md"};function p(l,a,r,h,d,u){return i(),n("div",null,[...a[0]||(a[0]=[e('<h1 id="【模型接入】suno" tabindex="-1">【模型接入】Suno <a class="header-anchor" href="#【模型接入】suno" aria-label="Permalink to &quot;【模型接入】Suno&quot;">​</a></h1><p>Suno AI，简称 Suno，是一款生成式人工智能音乐创作程序，旨在产生人声与乐器相结合的逼真歌曲。2023 年 12 月 20 日，Suno AI 在推出网络应用程序并与微软建立合作关系后，开始广泛使用。</p><p>由于 Suno 没有直接提供 API 接口，所以大家一般通过 <a href="https://github.com/gcui-art/suno-api" target="_blank" rel="noreferrer">https://github.com/gcui-art/suno-api</a> 项目，模拟用户操作，实现 API 形式调用 AI 生成音乐。</p><p>也因此，Spring AI 肯定是不集成 Suno 的，所以我们实现的 <code>models/suno</code> 包下的 SunoApi 类，基于上述的 <code>suno-api</code> 代理，调用 Suno 实现音乐生成的功能。</p><h2 id="_1-申请密钥" tabindex="-1">1. 申请密钥 <a class="header-anchor" href="#_1-申请密钥" aria-label="Permalink to &quot;1. 申请密钥&quot;">​</a></h2><p>可参考 <a href="https://github.com/gcui-art/suno-api/blob/main/README_CN.md" target="_blank" rel="noreferrer">https://github.com/gcui-art/suno-api/blob/main/README_CN.md</a> 文档，申请 Suno 账号，并搭建 <code>suno-api</code> 代理。</p><p>我是采用【本地运行】的方式，因为 Vercel 部署需要 VPN 访问，比较麻烦。</p><hr><p>申请完成后，可以在我们系统的 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单，进行密钥的配置。需要填写“密钥” + “自定义 API URL”。如下图所示：</p><p><img src="'+t+`" alt="私有的密钥配置"></p><h2 id="_2-如何使用" tabindex="-1">2. 如何使用？ <a class="header-anchor" href="#_2-如何使用" aria-label="Permalink to &quot;2. 如何使用？&quot;">​</a></h2><p>① 如果你的项目里需要直接通过 <code>@Resource</code> 注入 SunoApi 对象，需要把 <code>application.yaml</code> 配置文件里的 <code>yudao.ai.suno</code> 配置项，替换成你的！</p><div class="language-YAML vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">YAML</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">yudao</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ai</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    suno</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      enable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      base-url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://127.0.0.1:3001</span></span></code></pre></div><p>另外，由于 Suno 生成音乐是异步的，可以把项目的 AiSunoSyncJob 定时器类，配置每 1 分钟执行一次，同步音乐生成的结果。怎么使用定时器，可以参考 <a href="./../job">《定时任务》</a> 文档。</p><p>② 如果你希望使用 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单的密钥配置，则可以通过 AiModelService 的 <code>#getSunoApi()</code> 方法，获取对应的 SunoApi 对象。</p><p>另外，SunoApiTests 里有对应的测试用例，可以参考。</p>`,16)])])}const g=s(o,[["render",p]]);export{k as __pageData,g as default};
